WITH Base AS (SELECT *, DATE_TRUNC('WEEK', paid_at) AS paid_at_period FROM payments WHERE HOUR(paid_at) BETWEEN 8 AND 15), Agg AS (SELECT status, CASE WHEN amount >= 1600 THEN 'high' WHEN amount >= 690 THEN 'mid' ELSE 'low' END AS amount_bucket, MAX(amount) AS max_amount FROM Base GROUP BY status, CASE WHEN amount >= 1600 THEN 'high' WHEN amount >= 690 THEN 'mid' ELSE 'low' END) SELECT status, amount_bucket, max_amount FROM Agg WHERE max_amount > 1110;
